import{_ as a,o,c as r,a3 as t}from"./chunks/framework.DEy3KOfk.js";const u=JSON.parse('{"title":"Troubleshoot Bedrock pack hosting","description":"","frontmatter":{"editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/packages/bedrock-addon-manager/docs/troubleshooting.md"},"headers":[],"relativePath":"packages/bedrock-addon-manager/docs/troubleshooting.md","filePath":"packages/bedrock-addon-manager/docs/troubleshooting.md","lastUpdated":1791428389000}'),n={name:"packages/bedrock-addon-manager/docs/troubleshooting.md"};function d(s,e,c,i,l,p){return o(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="troubleshoot-bedrock-pack-hosting" tabindex="-1">Troubleshoot Bedrock pack hosting <a class="header-anchor" href="#troubleshoot-bedrock-pack-hosting" aria-label="Permalink to &quot;Troubleshoot Bedrock pack hosting&quot;">​</a></h1><h2 id="players-cannot-download-a-pack" tabindex="-1">Players cannot download a pack <a class="header-anchor" href="#players-cannot-download-a-pack" aria-label="Permalink to &quot;Players cannot download a pack&quot;">​</a></h2><p>Check that <code>web.enabled</code> is true, the pack appears in <code>/baddon list</code>, and the configured bind address and port are reachable through the server firewall. Confirm that <code>web.public_url</code> names the address clients use. If it is empty, check whether UPnPumpkin is installed and whether <code>web.port_forwarding</code> is enabled. Without a successful forward, the fallback is loopback and is not reachable from other machines.</p><p>The built-in server speaks plain HTTP. For HTTPS, configure a reverse proxy and set <code>web.public_url</code> to the proxy&#39;s client-facing address. When using external hosting, configure a <code>download_url</code> override for each pack and disable the built-in server if it is not needed.</p><h2 id="a-pack-is-missing-or-has-unexpected-metadata" tabindex="-1">A pack is missing or has unexpected metadata <a class="header-anchor" href="#a-pack-is-missing-or-has-unexpected-metadata" aria-label="Permalink to &quot;A pack is missing or has unexpected metadata&quot;">​</a></h2><p>The plugin scans only at server startup and <code>/baddon reload</code>. Check the server log for manifest errors, then run <code>/baddon list</code> after reloading. An <code>.mcaddon</code> can contain behavior packs and resource packs; only resource packs are extracted. For extracted files, key overrides by the effective name reported by <code>/baddon list</code>, not by an assumed inner filename.</p><p>Set <code>overrides.&quot;&lt;file&gt;&quot;.enabled = false</code> to omit one pack, or adjust its order there. Changes to the plugin config take effect on reload or restart. The plugin never edits <code>pumpkin.toml</code>.</p><h2 id="packs-are-not-offered-to-joining-players" tabindex="-1">Packs are not offered to joining players <a class="header-anchor" href="#packs-are-not-offered-to-joining-players" aria-label="Permalink to &quot;Packs are not offered to joining players&quot;">​</a></h2><p>This is a current Pumpkin API limitation: Pumpkin does not provide a resource-pack delivery API. BedrockAddonManager can scan and serve files, but cannot send a pack offer or enforce downloads. Accordingly, <code>packs.force</code> currently has no effect.</p>',9)])])}const k=a(n,[["render",d]]);export{u as __pageData,k as default};
